// Throwaway flow prototype. No production entry imports it. All ports and effects are local mocks.
import * as React from "react";
import { createRoot } from "react-dom/client";
import { MemoryRouter } from "react-router-dom";
import { ThemeProvider } from "next-themes";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import ReactMarkdown from "react-markdown";
import { ArrowLeft, ArrowRight, Check, ChevronRight, FileText, Plus, Search, ShieldCheck, Trash2, Upload, Users } from "lucide-react";
import { AgentPresenceProvider } from "@/components/ui/paige/AgentPresenceContext";
import { TenantCommandCenterShell } from "@/components/tenant-shell/TenantCommandCenterShell";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import "@/index.css";
import "@/solo/solo-tokens.css";
import "./agreements-preparation.css";

type Step = "register" | "source" | "document" | "recipients" | "fields" | "review" | "detail" | "history" | "correction" | "recipient" | "templates" | "template-editor" | "template-record";
type Condition = "ready" | "loading" | "empty" | "error" | "denied" | "offline" | "stale" | "expired" | "uncertain";
type Signer = { id: string; name: string; email: string; role: string };
type Field = { id: number; signer: string; type: string; page: number; x: number; y: number; required: boolean };
type Draft = { jurisdiction?:string; reviewRoute?:string; reviewer?:string; title: string; client: string; body: string; source: string; offer: string; uploadName: string; signers: Signer[]; fields: Field[]; ordered: boolean; revision: number; updatedAt?: string };
type Correction = { title:string;body:string;baseTitle:string;baseBody:string;baseStamp:string;baseVersion:number;phase:'editing'|'unknown'|'conflict';checked:boolean };
type Template = { id:string; title:string; body:string; version:number; jurisdiction:string; reviewRoute:string; reviewer:string; previousId:string|null };
type TemplateEdit = Template & { phase:'editing'|'unknown'|'conflict'; checked:boolean };
const librarySteps:Step[]=['templates','template-editor','template-record'];
const suppliedTemplate:Template={id:'synthetic-template-original',title:'Supplied service wording',body:'# Business-supplied wording\n\nThis synthetic document represents wording supplied by the business. No clause or completed legal review is inferred.',version:1,jurisdiction:'',reviewRoute:'unspecified',reviewer:'',previousId:null};
const correctionFor=(draft:Draft):Correction=>({title:draft.title,body:draft.body,baseTitle:draft.title,baseBody:draft.body,baseStamp:draft.updatedAt??'mock-original-save',baseVersion:draft.revision,phase:'editing',checked:false});
const steps: Step[] = ["document", "recipients", "fields", "review"];
const labels = { document: "Document", recipients: "Recipients", fields: "Fields", review: "Review" };
const sources = [["Business template", "Use a version from your governed template library.", FileText], ["Existing PDF", "Keep the exact uploaded pages. Add recipients and fields next.", Upload], ["PAIGE proposal", "Draft with MERIT using authorized business context, then review.", ShieldCheck], ["Blank document", "Compose a new agreement and retain its revisions.", Plus]] as const;
const initial: Draft = { jurisdiction:'',reviewRoute:'unspecified',reviewer:'',title: "Client services agreement", client: "", source: "Blank document", offer: "", uploadName: "", revision: 1, ordered: true,
  body: "# Services agreement\n\nBetween your business and the selected client.\n\n## Scope of services\n\nDescribe the services, deliverables, responsibilities and acceptance criteria.\n\n## Commercial terms\n\nSpecify the approved principal, payment schedule and due dates.\n\n## Review and completion\n\nDescribe how the client reviews each deliverable and requests revisions.\n\nThis demonstration contains placeholders. It is not an approved legal template.",
  signers: [{ id: "client", name: "", email: "", role: "Client" }], fields: [] };
const mockTemplate = "# Client services agreement\n\nPrepared by Sample Service Studio for Fern Studio.\n\n## The work\n\nA ten-month advisory engagement. The scope, delivery milestones, responsible staff and client acceptance criteria require owner review before sending.\n\n## Fees and payment schedule\n\nThe proposed principal is $3,500 USD: $500 down and ten monthly principal payments of $300. Exact dates, taxes, fees, cancellation and refund terms are required before approval.\n\n## Delivery and acceptance\n\nEach release identifies its deliverable version. Client approval or a revision request is recorded separately from task completion.\n\n## Other terms\n\nInsert reviewed jurisdiction-specific terms. This is synthetic review content, not legally approved language.";
const params = new URLSearchParams(location.search);
const theme = params.get("theme") === "dark" ? "dark" : "light";
localStorage.setItem("paige.agentRail.collapsed", String(params.get("paige") !== "open"));
localStorage.setItem("paige.tenantShell.navExpanded", "false");
(globalThis as { __React?: typeof React }).__React = React;

function Workspace() {
  const [business, setBusiness] = React.useState("sample-a");
  const [draft, setDraft] = React.useState<Draft>(() => {
    const fixture = params.get('step') === 'correction' ? { ...initial, client: 'Fern Studio', body: mockTemplate } : initial;
    try { return JSON.parse(sessionStorage.getItem("e04-prototype-sample-a") || "null") || fixture; } catch { return fixture; }
  });
  const [step, setStep] = React.useState<Step>(["register", "source", ...steps, "detail", "history", "correction", "recipient",...librarySteps].includes(params.get("step") || "") ? params.get("step") as Step : "register");
  const [templates,setTemplates]=React.useState<Template[]>(()=>{try{return JSON.parse(sessionStorage.getItem('e04-prototype-template-sample-a')||'null')||[suppliedTemplate];}catch{return [suppliedTemplate];}});
  const [templateId,setTemplateId]=React.useState(suppliedTemplate.id);
  const [templateEdit,setTemplateEdit]=React.useState<TemplateEdit|null>(null);
  const [templateResponse,setTemplateResponse]=React.useState('acknowledged');
  const [templateQuery,setTemplateQuery]=React.useState('');
  const [templateLeave,setTemplateLeave]=React.useState(false);
  const templateTitle=React.useRef<HTMLInputElement>(null),templateBody=React.useRef<HTMLTextAreaElement>(null);
  const [condition, setCondition] = React.useState<Condition>("ready");
  const [status, setStatus] = React.useState("Draft");
  const [filter, setFilter] = React.useState("All agreements");
  const [search, setSearch] = React.useState("");
  const [notice, setNotice] = React.useState("");
  const [error, setError] = React.useState("");
  const [dialog, setDialog] = React.useState<"leave" | "void" | "leave-correction" | null>(null);
  const [pending, setPending] = React.useState(false);
  const [saved, setSaved] = React.useState(false);
  const [previewOnly, setPreviewOnly] = React.useState(false);
  const returnFocus = React.useRef<HTMLElement | null>(null);
  const openDialog = (value: "leave" | "void" | "leave-correction") => { returnFocus.current = document.activeElement as HTMLElement; setDialog(value); };
  const [selectedField, setSelectedField] = React.useState<number | null>(null);
  const [historical, setHistorical] = React.useState(2);
  const [older, setOlder] = React.useState(false);
  const [correction,setCorrection]=React.useState<Correction|null>(()=>params.get('step')==='correction'?correctionFor(draft):null);
  const [correctionResult,setCorrectionResult]=React.useState('acknowledged');
  const correctionClock=React.useRef(0),correctionTitle=React.useRef<HTMLInputElement>(null),correctionBody=React.useRef<HTMLTextAreaElement>(null);
  const [consent, setConsent] = React.useState(false);
  const [read, setRead] = React.useState(false);
  const [signature, setSignature] = React.useState("");
  const [decision, setDecision] = React.useState("Pending review");
  const heading = React.useRef<HTMLHeadingElement>(null);
  const textarea = React.useRef<HTMLTextAreaElement>(null);
  React.useEffect(() => { heading.current?.focus(); }, [step]);
  React.useEffect(() => { sessionStorage.setItem(`e04-prototype-${business}`, JSON.stringify(draft)); }, [draft, business]);
  React.useEffect(()=>{sessionStorage.setItem(`e04-prototype-template-${business}`,JSON.stringify(templates));},[templates,business]);
  const change = (patch: Partial<Draft>) => { setDraft(d => ({ ...d, ...patch })); setSaved(false); setPending(false); setError(""); };
  const go = (value: Step) => { const nextURL = new URL(location.href); nextURL.searchParams.set("step", value); history.replaceState(null, "", nextURL); setPreviewOnly(false); setStep(value); setError(""); setNotice(""); };
  const invalid = () => draft.source === "Existing PDF" && !draft.uploadName ? "Select a supported PDF before continuing." : !draft.client ? "Select the client this agreement belongs to." : !draft.title.trim() || !draft.body.trim() ? "Add a title and document content." :
    !draft.signers.length || draft.signers.some(s => !s.name.trim() || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s.email)) ? "Add a name and valid email for every recipient." :
    new Set(draft.signers.map(s => s.email.trim().toLowerCase())).size !== draft.signers.length ? "Each recipient needs a different email." :
    draft.signers.some(s => !draft.fields.some(f => f.signer === s.id && f.type === "Signature" && f.required)) ? "Place a required signature for every signer." : "";
  const next = () => {
    const message = step === "document" ? (draft.source === "Existing PDF" && !draft.uploadName ? "Select a supported PDF before continuing." : !draft.client ? "Select a client before continuing." : !draft.title.trim() || !draft.body.trim() ? "Add a title and document content." : "") : step === "recipients" ? invalid().replace(/^Place a required signature.*$/, "") : invalid();
    if (message) { setError(message); requestAnimationFrame(() => document.querySelector<HTMLElement>('[data-error-summary]')?.focus()); return; }
    go(steps[Math.min(3, steps.indexOf(step) + 1)]);
  };
  const save = () => {
    if (["offline", "stale", "uncertain"].includes(condition)) { setError(condition === "stale" ? "A newer revision exists. Compare it before saving; your edits are retained." : "The save could not be confirmed. Your local edits remain. Re-read before retrying."); return; }
    setSaved(true); setNotice("Draft retained in this local prototype. No business record was written.");
  };
  const beginCorrection=()=>{
    if(status!=='Draft'||draft.source==='Existing PDF'){setNotice('This record is not an editable text draft. Preserve its existing wording and signing evidence.');return;}
    setCorrection(correctionFor(draft));go('correction');
  };
  const applyMockCorrection=(value:Correction)=>{
    const stamp=`mock-native-save-${++correctionClock.current}`;
    setDraft(current=>({...current,title:value.title,body:value.body,
      revision:current.body===value.body?current.revision:current.revision+1,updatedAt:`${stamp}:${current.updatedAt??'original'}`}));setSaved(true);
  };
  const submitCorrection=(event:React.FormEvent)=>{
    event.preventDefault();if(!correction||correction.phase!=='editing'||condition!=='ready'||status!=='Draft')return;
    if(!correction.title.trim()){setError('Add a title before saving.');correctionTitle.current?.focus();return;}
    if(!correction.body.trim()){setError('Add the intended agreement wording.');correctionBody.current?.focus();return;}
    setError('');
    if(correctionResult==='refused'){setCorrection(null);setCondition('denied');return;}
    if(correctionResult==='conflict'){
      const stamp=`mock-other-save-${++correctionClock.current}`;
      setDraft(current=>({...current,body:'A different authorized correction is currently recorded.',revision:current.revision+1,updatedAt:`${stamp}:${current.updatedAt??'original'}`}));
      setCorrection({...correction,phase:'conflict',checked:false});return;
    }
    if(correctionResult==='lost-saved'||correctionResult==='acknowledged')applyMockCorrection(correction);
    if(correctionResult==='acknowledged'){setCorrection(null);go('detail');setNotice('Synthetic native acknowledgment only: the same original agreement was corrected. No signing, payment or notification occurred.');}
    else setCorrection({...correction,phase:'unknown',checked:false});
  };
  const retryCorrection=()=>{
    if(!correction||!correction.checked||condition!=='ready')return;
    if((draft.updatedAt??'mock-original-save')!==correction.baseStamp){setCorrection({...correction,phase:'conflict'});return;}
    // SAME frozen proposal/baseline, never a refreshed timestamp or new intent.
    applyMockCorrection(correction);setCorrection(null);go('detail');setNotice('Synthetic acknowledgment for the same reviewed correction. Original agreement/client identity unchanged.');
  };
  const chooseSource = (source: string) => {
    if(source==='Business template'){go('templates');return;}
    change({ source, uploadName: "", body: source === "Blank document" ? initial.body : mockTemplate }); go("document");
    if (source === "PAIGE proposal") setNotice("Demonstration draft only. Production must cite authorized business Knowledge and ask for missing commercial details.");
  };
  const toolbar = (prefix: string, suffix = "") => {
    const el = textarea.current; if (!el) return;
    const a = el.selectionStart, b = el.selectionEnd;
    change({ body: draft.body.slice(0, a) + prefix + draft.body.slice(a, b) + suffix + draft.body.slice(b) });
    requestAnimationFrame(() => { el.focus(); el.setSelectionRange(a + prefix.length, b + prefix.length); });
  };
  const switchBusiness = () => {
    const to = business === "sample-a" ? "sample-b" : "sample-a";
    let restored = initial; try { restored = JSON.parse(sessionStorage.getItem(`e04-prototype-${to}`) || "null") || initial; } catch { /* malformed synthetic draft is ignored */ }
    let library:Template[]=[];try{library=JSON.parse(sessionStorage.getItem(`e04-prototype-template-${to}`)||'null')||[];}catch{/* Ignore malformed synthetic library only. */}
    setBusiness(to); setDraft(restored);setTemplates(library);setTemplateEdit(null);setTemplateQuery('');setTemplateLeave(false); setCorrection(null); setSaved(false); setPending(false); go("register");
  };
  const selectedTemplate=templates.find(value=>value.id===templateId);
  const beginTemplate=(source:Template|null)=>{
    setTemplateEdit({...source??{title:'',body:'',jurisdiction:'',reviewRoute:'unspecified',reviewer:''},id:crypto.randomUUID(),version:source?source.version+1:1,previousId:source?.id??null,phase:'editing',checked:false});go('template-editor');
  };
  const storeTemplate=(value:TemplateEdit)=>{
    const row:Template={id:value.id,title:value.title,body:value.body,version:value.version,jurisdiction:value.jurisdiction,reviewRoute:value.reviewRoute,reviewer:value.reviewer,previousId:value.previousId};
    setTemplates(current=>current.some(item=>item.id===row.id)?current:[row,...current]);setTemplateId(row.id);
  };
  const submitTemplate=(event:React.FormEvent)=>{
    event.preventDefault();if(!templateEdit||templateEdit.phase!=='editing'||condition!=='ready')return;
    if(!templateEdit.title.trim()){setError('Name this template.');templateTitle.current?.focus();return;}
    if(!templateEdit.body.trim()){setError('Add the wording supplied by your business.');templateBody.current?.focus();return;}
    if(templateResponse==='refused'){setTemplateEdit(null);setCondition('denied');return;}
    if(templateResponse==='conflict'){setTemplateEdit({...templateEdit,phase:'conflict'});setError('The source version changed. Compare it before preparing another version.');return;}
    if(templateResponse==='acknowledged'||templateResponse==='lost-saved')storeTemplate(templateEdit);
    if(templateResponse==='acknowledged'){setTemplateEdit(null);go('template-record');setNotice('Synthetic acknowledgment: exact supplied wording retained as a template version. No completed review is recorded.');}
    else setTemplateEdit({...templateEdit,phase:'unknown'});
  };
  const recoverTemplate=()=>{
    if(!templateEdit)return;const actual=templates.find(value=>value.id===templateEdit.id);
    if(actual){setTemplateId(actual.id);setTemplateEdit(null);go('template-record');setNotice('Recovered this exact synthetic request and stored version.');}
    else{setTemplateEdit({...templateEdit,checked:true});setNotice('The original synthetic request is unconfirmed. Missing acknowledgment is not a failed save.');}
  };
  const useTemplate=(value:Template)=>{
    change({source:'Business template',title:value.title,body:value.body,jurisdiction:value.jurisdiction,reviewRoute:value.reviewRoute,reviewer:value.reviewer,uploadName:''});go('document');setNotice(`Using exact synthetic template version ${value.version}. Select the client and review the intended terms.`);
  };
  const documentPreview = <article className="agp-paper" aria-label="Draft document preview"><div className="agp-document-mark"><FileText size={16}/><span>Document preview · revision {draft.revision}</span></div><ReactMarkdown>{draft.body}</ReactMarkdown><div className="agp-paper-end">End of draft · preparation preview, not frozen signing PDF</div>{step === "fields" && draft.fields.map(f => <button key={f.id} style={{ left: `${f.x}%`, top: `${f.y}%` }} className="agp-placed" aria-pressed={f.id === selectedField} onClick={() => setSelectedField(f.id)}>{f.type} · {draft.signers.find(s => s.id === f.signer)?.name || "Recipient"}</button>)}</article>;
  const activeField = draft.fields.find(f => f.id === selectedField);
  const patchField = (patch: Partial<Field>) => change({ fields: draft.fields.map(f => f.id === selectedField ? { ...f, ...patch } : f) });
  const headline = condition === "denied" ? "Agreement access required" : step === "templates" ? "Business templates" : step === "template-editor" ? templateEdit?.previousId?'Prepare a new version':'Create a business template' : step === "template-record" ? selectedTemplate?.title||'Template version' : step === "register" ? "Terms & Agreements" : step === "source" ? "Start an agreement" : step === "recipient" ? "Review your agreement" : draft.title;
  const special = ["loading", "error", "denied", "expired"].includes(condition);
  return <>
    <details className="agp-review-tools"><summary>Flow prototype · synthetic data and effects · review controls</summary><div>
      <label>State<select aria-label="State" value={condition} onChange={e => setCondition(e.target.value as Condition)}>{["ready", "loading", "empty", "error", "denied", "offline", "stale", "expired", "uncertain"].map(c => <option key={c}>{c}</option>)}</select></label>
      <label>Path<select aria-label="Path" value={step} onChange={e => go(e.target.value as Step)}>{["register", "source", ...steps, "detail", "history", "correction", "recipient",...librarySteps].map(s => <option key={s}>{s}</option>)}</select></label>
      <label>Recorded outcome<select aria-label="Recorded outcome" value={status} onChange={e => setStatus(e.target.value)}>{["Draft", "Awaiting signatures", "Partially signed", "Completed", "Declined", "Expired", "Voided"].map(s => <option key={s}>{s}</option>)}</select></label>
      <label>Mock correction response<select aria-label="Mock correction response" value={correctionResult} onChange={event=>setCorrectionResult(event.target.value)}><option value="acknowledged">Native acknowledgment</option><option value="lost-saved">Lost response, stored correction</option><option value="lost-pending">Lost response, original still shown</option><option value="conflict">Concurrent correction</option><option value="refused">Native authority refusal</option></select></label>
      <label>Mock template response<select aria-label="Mock template response" value={templateResponse} onChange={event=>setTemplateResponse(event.target.value)}><option value="acknowledged">Native acknowledgment</option><option value="lost-saved">Lost response, stored version</option><option value="lost-pending">Lost response, request unconfirmed</option><option value="conflict">Stale original source</option><option value="refused">Native authority refusal</option></select></label><button onClick={switchBusiness}>Switch synthetic business</button><label>Lead design review<select aria-label="Lead design review" value={decision} onChange={e => setDecision(e.target.value)}><option>Pending review</option><option>Approve design intent</option><option>Revise</option><option>Reject</option></select></label><label>Review notes<input placeholder="Local review notes only"/></label>
      <p>All identities, templates, Knowledge, saves, approval, transport and signatures are mocked. Native haptics, backend integrity and production acceptance are unverified. Stage changes use150ms emphasis; reduced motion is immediate. No actual sends, uploads, signatures or payments.</p>
    </div></details>
    <section className={`agp ${steps.includes(step)||step==='template-editor' ? "agp-preparing" : ""} ${previewOnly ? "agp-show-document" : ""}`} aria-label="Agreements flow prototype" data-mock-agreement-id={`${business}:synthetic-original-agreement`}>
      <div className="agp-top"><div><button className="agp-back" onClick={() => step==='template-editor'&&templateEdit?setTemplateLeave(true):steps.includes(step) && !saved ? openDialog("leave") : go("register")}><ArrowLeft size={15}/>Sales / Agreements</button><h1 ref={heading} tabIndex={-1}>{headline}</h1><p>{condition === "denied" ? "Confirm original business and role access before viewing agreement details." : step === "register" ? "Prepare the relationship. Follow every signature. Keep the original record." : step === "source" ? "Begin with the right source. Review the content before anyone signs." : librarySteps.includes(step)?"Original wording. Retained versions. A clear starting point for each engagement.": `${draft.client || "Choose a client"} · ${business === "sample-a" ? "Sample Service Studio" : "Other sample business"} · ${draft.source}`}</p></div><div className="agp-actions">{step === "register" ? <button className="agp-primary" onClick={() => go("source")}><Plus size={16}/>New agreement</button> : step==='templates'?<button className="agp-primary" onClick={()=>beginTemplate(null)}><Plus size={16}/>New template</button>:steps.includes(step) ? <><span className="agp-state">{saved ? "Local draft retained" : "Unsaved local changes"}</span><button onClick={save}>Save draft</button></> : <span className="agp-state">{status}</span>}</div></div>
      {steps.includes(step) && <nav className="agp-steps" aria-label="Agreement preparation">{steps.map((s, i) => <button key={s} aria-current={step === s ? "step" : undefined} onClick={() => go(s)}><span>{i + 1}</span>{labels[s as keyof typeof labels]}{i < 3 && <ChevronRight size={14}/>}</button>)}</nav>}
      {steps.includes(step) && <button className="agp-mobile-preview" aria-pressed={previewOnly} onClick={() => setPreviewOnly(!previewOnly)}><FileText size={16}/>{previewOnly ? "Return to preparation" : "Preview document"}</button>}
      {notice && <p className="agp-notice" role="status">{notice}</p>}
      {error && <div className="agp-error" role="alert" tabIndex={-1} data-error-summary>{error}</div>}
      {step==='templates'&&!special&&<section aria-label="Business template library">
        <div className="agp-register-controls"><label className="agp-search"><Search size={17}/><span className="sr-only">Find a business template</span><input type="search" value={templateQuery} onChange={event=>setTemplateQuery(event.target.value)} placeholder="Template title"/></label><p className="agp-muted">Retained wording is separate from completed legal review.</p></div>
        {condition==='empty'||!templates.filter(value=>value.title.toLowerCase().includes(templateQuery.toLowerCase())).length?<div className="agp-blank"><FileText size={30}/><h2>{templateQuery?'No matching templates':'Create your first business template'}</h2><p>Start with wording supplied by your business. Jurisdiction and wording-review options can be set when relevant.</p><button onClick={()=>setTemplateQuery('')}>Clear search</button><button className="agp-primary" onClick={()=>beginTemplate(null)}>Create a template</button></div>:<div className="agp-template-list">{templates.filter(value=>value.title.toLowerCase().includes(templateQuery.toLowerCase())).map(value=><button key={value.id} className="agp-template-row" onClick={()=>{setTemplateId(value.id);go('template-record');}}><FileText size={24}/><span><strong>{value.title}</strong><small>Version {value.version} · supplied business wording</small></span><ArrowRight size={16}/></button>)}</div>}
      </section>}
      {step==='template-editor'&&!special&&<>
        {!templateEdit?<div className="agp-blank"><h2>No template edit is open</h2><button onClick={()=>go('templates')}>Return to templates</button></div>:<>
          <button className="agp-mobile-preview" aria-pressed={previewOnly} onClick={()=>setPreviewOnly(!previewOnly)}>{previewOnly?'Return to template editing':'Preview template'}</button>
          <form className="agp-layout" onSubmit={submitTemplate} aria-label="Template version editor" data-template-request={templateEdit.id}>
            <div className="agp-editor"><div className="agp-section-title"><h2>{templateEdit.previousId?'New wording version':'Your business wording'}</h2><span className="agp-state">Version {templateEdit.version}</span></div>
              <label>Template title<input ref={templateTitle} value={templateEdit.title} disabled={templateEdit.phase!=='editing'||condition!=='ready'} onChange={event=>setTemplateEdit({...templateEdit,title:event.target.value})}/></label>
              <label>Supplied template wording<textarea ref={templateBody} rows={13} value={templateEdit.body} readOnly={templateEdit.phase!=='editing'||condition!=='ready'} onChange={event=>setTemplateEdit({...templateEdit,body:event.target.value})}/></label>
              <details className="agp-wording-options"><summary>Jurisdiction &amp; wording review</summary><p>Optional configuration for this exact wording. Completed review is recorded separately.</p>
                <label>Jurisdiction<input value={templateEdit.jurisdiction} disabled={templateEdit.phase!=='editing'} onChange={event=>setTemplateEdit({...templateEdit,jurisdiction:event.target.value})}/></label>
                <label>Requested wording review<select value={templateEdit.reviewRoute} disabled={templateEdit.phase!=='editing'} onChange={event=>setTemplateEdit({...templateEdit,reviewRoute:event.target.value,reviewer:event.target.value==='unspecified'?'':templateEdit.reviewer})}><option value="unspecified">Not specified</option><option value="business">Business review</option><option value="qualified_legal">Qualified legal review</option></select></label>
                {templateEdit.reviewRoute!=='unspecified'&&<label>Reviewer or review team<input value={templateEdit.reviewer} disabled={templateEdit.phase!=='editing'} onChange={event=>setTemplateEdit({...templateEdit,reviewer:event.target.value})}/></label>}
              </details>
              {templateEdit.phase==='editing'?<button className="agp-primary" type="submit" disabled={condition!=='ready'}>Save template version</button>:<div className="agp-error" role="status"><h3>{templateEdit.phase==='conflict'?'Source version changed':'Template result unconfirmed'}</h3><p>The reviewed proposal is preserved. Read the same request before deciding whether to retry.</p><button type="button" onClick={recoverTemplate}>Read original template request</button>{templateEdit.checked&&templateEdit.phase==='unknown'&&<button type="button" onClick={()=>{storeTemplate(templateEdit);setTemplateEdit(null);go('template-record');setNotice('Synthetic acknowledgment for the SAME reviewed request and wording.');}}>Retry same template request</button>}</div>}
              <button type="button" onClick={()=>setTemplateLeave(true)}>Return to templates</button><p className="agp-muted">Saving retains wording. It does not complete legal review or request signatures.</p>
            </div>
            <article className="agp-paper" aria-label="Template wording preview"><div className="agp-document-mark"><FileText size={16}/><span>Template · version {templateEdit.version}</span></div><h2>{templateEdit.title||'Untitled template'}</h2>{templateEdit.body?<ReactMarkdown>{templateEdit.body}</ReactMarkdown>:<p>Add your business wording to see the document here.</p>}<div className="agp-paper-end">Preparation preview · no signed document</div></article>
          </form>
        </>}
      </>}
      {step==='template-record'&&!special&&<>
        {!selectedTemplate?<div className="agp-blank"><h2>The original template version is unavailable</h2><button onClick={()=>go('templates')}>Return to templates</button></div>:<div className="agp-layout"><aside className="agp-editor"><h2>Retained template version</h2><span className="agp-state">Version {selectedTemplate.version}</span><dl className="agp-facts"><dt>Jurisdiction</dt><dd>{selectedTemplate.jurisdiction||'Not specified'}</dd><dt>Requested review</dt><dd>{selectedTemplate.reviewRoute==='qualified_legal'?'Qualified legal review':selectedTemplate.reviewRoute==='business'?'Business review':'Not specified'}</dd><dt>Reviewer</dt><dd>{selectedTemplate.reviewer||'Not specified'}</dd><dt>Completed review</dt><dd>No completed review is recorded</dd></dl><button className="agp-primary" onClick={()=>useTemplate(selectedTemplate)}>Use this version<ArrowRight size={16}/></button><button onClick={()=>beginTemplate(selectedTemplate)}>Prepare a new version</button><button onClick={()=>go('templates')}>Return to templates</button><p className="agp-muted">Earlier retained wording remains available. A new version does not revise existing client agreements.</p></aside><article className="agp-paper" aria-label="Stored template wording"><h2>{selectedTemplate.title}</h2><ReactMarkdown>{selectedTemplate.body}</ReactMarkdown><div className="agp-paper-end">Exact synthetic stored version · no legal sufficiency claim</div></article></div>}
      </>}
      <Dialog open={templateLeave} onOpenChange={setTemplateLeave}><DialogContent><DialogHeader><DialogTitle>Leave this template proposal?</DialogTitle><DialogDescription>{templateEdit?.phase==='unknown'?'The original request may still finish. Leaving does not cancel it. Read the stored version before starting another request.':'The unsaved proposal will be discarded. Existing retained versions stay available.'}</DialogDescription></DialogHeader><DialogFooter><button onClick={()=>setTemplateLeave(false)}>Keep editing template</button><button onClick={()=>{setTemplateEdit(null);setTemplateLeave(false);go('templates');}}>Leave template proposal</button></DialogFooter></DialogContent></Dialog>
      {step === "detail" && <section className="agp-wording-options" aria-label="Recorded preparation options"><h2>Preparation options</h2><dl className="agp-facts"><dt>Jurisdiction</dt><dd>{draft.jurisdiction||'Not specified'}</dd><dt>Requested review</dt><dd>{draft.reviewRoute==='qualified_legal'?'Qualified legal review':draft.reviewRoute==='business'?'Business review':'Not specified'}</dd>{draft.reviewer&&<><dt>Reviewer</dt><dd>{draft.reviewer}</dd></>}</dl><p>Configuration only. No completed review or legal sufficiency is recorded.</p></section>}{step === "detail" && <button onClick={() => go("history")}>Inspect wording history</button>}
      {step === "detail" && <button onClick={beginCorrection}>Correct draft wording</button>}
      {step === 'correction' && !special && <>
        {!correction||status!=='Draft'||condition==='empty' ? <div className="agp-blank"><h2>No editable draft is available</h2><p>Preserve signed or frozen wording. Return to the original record to review the available authorized actions.</p><button onClick={()=>go('detail')}>Return to agreement</button></div> : <form className="agp-layout" onSubmit={submitCorrection} data-mock-agreement-id={`${business}:synthetic-original-agreement`}>
          <div className="agp-editor"><h2>Correct draft wording</h2><p>The original client, offer and commercial references stay with this agreement.</p>
            <label>Draft title<input ref={correctionTitle} value={correction.title} disabled={correction.phase!=='editing'||condition!=='ready'} onChange={event=>setCorrection({...correction,title:event.target.value})}/></label>
            <label>Draft wording<textarea ref={correctionBody} rows={12} value={correction.body} readOnly={correction.phase!=='editing'||condition!=='ready'} onChange={event=>setCorrection({...correction,body:event.target.value})}/></label>
            <p className="agp-muted">Changing wording does not change invoices, payment obligations or completed services. Review commercial terms before requesting signatures.</p>
            {correction.phase==='editing' ? <button className="agp-primary" type="submit" disabled={condition!=='ready'}>Save draft correction</button> : <div className="agp-error" role="status"><h3>{correction.phase==='unknown'?'Correction result unconfirmed':'The original agreement changed'}</h3><p>The proposed wording is preserved. The original request may still finish; a missing acknowledgment does not prove success or failure.</p><button type="button" onClick={()=>setCorrection({...correction,checked:true})}>Read current original record</button>{correction.checked&&<><p>Current source differs from original save: {(draft.updatedAt??'mock-original-save')===correction.baseStamp?'No recorded change shown':'Yes'}. This read does not attribute an unconfirmed action.</p><button type="button" onClick={retryCorrection} disabled={correction.phase==='conflict'||(draft.updatedAt??'mock-original-save')!==correction.baseStamp}>Retry same reviewed correction</button></>}</div>}
            <button type="button" onClick={()=>openDialog('leave-correction')}>Return without another save</button>
          </div>
          <article className="agp-paper" aria-label="Correction review"><h2>Review the proposed change</h2><p>Original content version {correction.baseVersion} · same synthetic agreement</p><ReactMarkdown components={{img:({alt})=><span>[Embedded image: {alt||'document image'}]</span>}}>{correction.body}</ReactMarkdown>{correction.checked&&<><hr/><h3>Current recorded wording</h3><p>Content version {draft.revision} · original record</p><ReactMarkdown components={{img:({alt})=><span>[Embedded image: {alt||'document image'}]</span>}}>{draft.body}</ReactMarkdown></>}</article>
        </form>}
      </>}
      {step === "history" && <div className="agp-layout"><aside className="agp-editor"><h2>Wording history</h2><p>Saved wording stays with this agreement. Earlier versions may not have been retained.</p><button onClick={() => go("detail")}>Return to current agreement</button>{condition === "empty" ? <p role="status">No retained wording was returned. The current document remains available.</p> : condition === "ready" ? <><div className="agp-field-list">{(older ? [2,1] : [2]).map(revision => <button key={revision} aria-pressed={historical === revision} onClick={() => setHistorical(revision)}>Retained revision {revision} · Body version {revision}</button>)}</div>{!older && <button onClick={() => setOlder(true)}>Read older wording</button>}</> : <p role="status">{condition === "loading" ? 'Reading saved wording…' : condition === "denied" ? 'Agreement author access required' : 'Earlier wording could not be verified.'}</p>}{condition !== "ready" && <button onClick={() => setCondition("ready")}>Retry wording read</button>}<p className="agp-muted">Read-only review. No restore, signing, payment or external action occurs. Original source time and actual retention time are distinct.</p></aside>{condition === "ready" && <article className="agp-paper" aria-label="Retained wording"><h2>Retained revision {historical}</h2><p>Original body version {historical} · Synthetic retained record</p><ReactMarkdown>{historical === 1 ? '# Earlier advisory wording\n\nOriginal scope before the later correction.' : '# Corrected advisory wording\n\nRevised scope retained under the same agreement.'}</ReactMarkdown><p className="agp-muted">Draft wording is not evidence of an accepted signature or completed payment.</p></article>}</div>}
      {step !== "history" && ["offline", "stale", "uncertain"].includes(condition) && <div className="agp-error" role="status"><strong>{condition === "offline" ? "You’re offline" : condition === "stale" ? "This revision has changed" : "Outcome not confirmed"}</strong><p>Your edits are retained locally. Re-read the canonical record before retrying an action.</p><button onClick={() => { setCondition("ready"); setNotice("Synthetic read restored. No external action was repeated."); }}>Re-read status</button></div>}
      {special && step !== "history" ? <div className="agp-blank" role={condition === "error" ? "alert" : "status"}><FileText size={28}/><h2>{condition === "loading" ? "Reading the agreement…" : condition === "denied" ? "This role cannot prepare agreements" : condition === "expired" ? "This signing link has expired" : "The agreement could not be read"}</h2><p>{condition === "denied" ? "Ask an authorized owner to review this agreement. No additional access is granted here." : condition === "expired" ? "Request a new authorized signing link. The existing document is unchanged." : "No records or outcomes are inferred. Your local draft is retained."}</p><button onClick={() => setCondition("ready")}>{condition === "loading" ? "Complete mock read" : "Return to available record"}</button></div> : <>
      {step === "register" && <><button onClick={()=>go('templates')}>Business templates<ArrowRight size={16}/></button><div className="agp-register-controls"><label className="agp-search"><Search size={17}/><span className="sr-only">Find an agreement</span><input type="search" placeholder="Client, document or signer" value={search} onChange={e => setSearch(e.target.value)}/></label><label>Signature state<select value={filter} onChange={e => setFilter(e.target.value)}>{["All agreements", "Draft", "Awaiting signatures", "Partially signed", "Completed", "Declined", "Expired", "Voided"].map(s => <option key={s}>{s}</option>)}</select></label></div>
        {condition === "empty" || (search && !`${draft.title} Fern Studio Avery Lee`.toLowerCase().includes(search.toLowerCase())) || (filter !== "All agreements" && filter !== status) ? <div className="agp-blank"><FileText size={30}/><h2>{condition === "empty" ? "Your next engagement starts here" : "No matching agreements"}</h2><p>{condition === "empty" ? "Create a draft for a real client. Nothing is sent until the document and recipients are reviewed and authorized." : "Try another document, client or signature state."}</p><button onClick={() => { setSearch(""); setFilter("All agreements"); setCondition("ready"); }}>Clear filters</button><button className="agp-primary" onClick={() => go("source")}>Create a draft</button></div> : <div className="agp-register"><div className="agp-register-head"><span>Agreement / client</span><span>Signature progress</span><span>Next action</span></div><button className="agp-record" onClick={() => go(status === "Draft" ? "document" : "detail")}><span className="agp-doc-icon"><FileText size={23}/></span><span><strong>{draft.title}</strong><small>Fern Studio · revision {draft.revision} · synthetic record</small></span><span><span className="agp-state">{status}</span><small>{status === "Draft" ? "No signature request issued" : status === "Completed" ? `${draft.signers.length} of ${draft.signers.length} signers · mock evidence` : `0 of ${draft.signers.length} signers · mock progress`}</small></span><span>{status === "Draft" ? "Continue preparation" : "Inspect record"}<ArrowRight size={16}/></span></button><div className="agp-register-foot">Every document revision stays with its original client. A request, delivery, opening and signature are separate events.</div></div>}
        <div className="agp-paige-line"><ShieldCheck size={20}/><div><strong>PAIGE can help prepare the next step</strong><p>Use the client, service scope and reviewed economics. Missing details stay questions.</p></div><button onClick={() => { go("source"); setNotice("Choose PAIGE proposal to inspect the synthetic preparation path. No Chat request is executed."); }}>Prepare with PAIGE<ArrowRight size={15}/></button></div></>}
      {step === "source" && <div className="agp-source"><div><h2>A reliable starting point</h2><p>The source becomes part of the agreement’s preparation history.</p>{sources.map(([title, detail, Icon]) => <button key={String(title)} onClick={() => chooseSource(String(title))}><Icon size={22}/><span><strong>{String(title)}</strong><small>{String(detail)}</small></span><ArrowRight size={17}/></button>)}</div><aside><h2>Before it goes out</h2><ol><li>Confirm the client, services and commercial terms.</li><li>Review the precise document and recipient assignments.</li><li>Authorize the signature request through the existing approval gate.</li></ol><p>A signature does not authorize a charge. Legal review of templates and jurisdiction-specific requirements remains separate.</p></aside></div>}
      {step === "document" && <div className="agp-layout"><div className="agp-editor"><div className="agp-form-row"><label>Agreement title<input value={draft.title} onChange={e => change({ title: e.target.value })}/></label><label>Client<select aria-label="Client" value={draft.client} onChange={e => change({ client: e.target.value, signers: [{ id: "client", name: e.target.value ? "Avery Lee" : "", email: e.target.value ? "avery@example.test" : "", role: "Client" }], fields: [] })}><option value="">Select a client</option><option>Fern Studio</option><option>Harbor Practice</option></select></label></div><label>Connected offer<select value={draft.offer} onChange={e => change({ offer: e.target.value })}><option value="">No offer selected</option><option>Advisory engagement · proposed $3,500 USD</option></select></label>{draft.source === "Existing PDF" ? <div className="agp-upload"><Upload size={26}/><label>Select a PDF<input type="file" accept="application/pdf,.pdf" onChange={e => { const file = e.target.files?.[0]; if (!file) return; if (file.type !== "application/pdf" || !file.name.toLowerCase().endsWith(".pdf") || file.size > 10 * 1024 * 1024) { setError("Choose a PDF up to10MB. Other formats are not supported by this prototype."); return; } change({ uploadName: file.name }); setNotice(`Local selection: ${file.name}. Upload, parsing and exact PDF preview are mocked; this selection is not a saved document.`); }}/></label><p>PDF preview and page geometry require the canonical retained-file pipeline. The adjacent sample is illustrative.</p></div> : <><div className="agp-editor-tools" role="toolbar" aria-label="Document formatting"><button onClick={() => toolbar("**", "**")}>Bold</button><button onClick={() => toolbar("## ")}>Heading</button><button onClick={() => toolbar("- ")}>List</button><span>Markdown editor · live draft preview</span></div><label>Document content<textarea ref={textarea} rows={20} value={draft.body} onChange={e => change({ body: e.target.value })}/></label></>}<div className="agp-source-note"><FileText size={17}/><span>{draft.source === "Business template" ? "Template library · synthetic version3. Exact governed source will be retained." : `${draft.source}. No reviewed legal sufficiency is implied.`}</span></div><details className="agp-wording-options"><summary>Jurisdiction &amp; wording review</summary><p>Set the jurisdiction and review route for this wording. Completed review is recorded separately.</p><label>Jurisdiction<input value={draft.jurisdiction??''} placeholder="Country, state, province or other jurisdiction" onChange={e=>change({jurisdiction:e.target.value})}/></label><label>Requested wording review<select value={draft.reviewRoute??'unspecified'} onChange={e=>change({reviewRoute:e.target.value,reviewer:e.target.value==='unspecified'?'':draft.reviewer})}><option value="unspecified">Not specified</option><option value="business">Business review</option><option value="qualified_legal">Qualified legal review</option></select></label>{draft.reviewRoute&&draft.reviewRoute!=='unspecified'&&<label>Reviewer or review team<input value={draft.reviewer??''} onChange={e=>change({reviewer:e.target.value})}/></label>}<p className="agp-muted">These options do not alter the document wording or authorize signing, sending or payment.</p></details></div>{documentPreview}</div>}
      {step === "recipients" && <div className="agp-layout"><div className="agp-editor"><h2>Who needs to sign?</h2><p>Use the intended signer’s own address. Keep internal reviewers separate from signing recipients.</p><label className="agp-check"><input type="checkbox" checked={draft.ordered} onChange={e => change({ ordered: e.target.checked })}/>Require recipients to sign in this order</label><ol className="agp-recipient-list">{draft.signers.map((s, i) => <li key={s.id}><div className="agp-section-title"><h3>{draft.ordered ? `Signer ${i + 1}` : "Signer"}</h3><button aria-label={`Remove signer ${i + 1}`} onClick={() => change({ signers: draft.signers.filter(x => x.id !== s.id), fields: draft.fields.filter(f => f.signer !== s.id) })}><Trash2 size={16}/></button></div><label>Full name<input value={s.name} onChange={e => change({ signers: draft.signers.map(x => x.id === s.id ? { ...x, name: e.target.value } : x) })}/></label><label>Email<input type="email" value={s.email} onChange={e => change({ signers: draft.signers.map(x => x.id === s.id ? { ...x, email: e.target.value } : x) })}/></label><label>Signing role<select value={s.role} onChange={e => change({ signers: draft.signers.map(x => x.id === s.id ? { ...x, role: e.target.value } : x) })}><option>Client</option><option>Business representative</option><option>Co-signer</option></select></label></li>)}</ol><button onClick={() => change({ signers: [...draft.signers, { id: `signer-${draft.signers.length + 1}-${Date.now()}`, name: "", email: "", role: "Business representative" }] })}><Plus size={16}/>Add signer</button><p className="agp-muted">Changing a recipient clears that recipient’s approval context. Existing sent versions cannot be edited.</p></div>{documentPreview}</div>}
      {step === "fields" && <div className="agp-layout"><div className="agp-editor"><h2>Assign the signing fields</h2><p>Every required signature belongs to a named recipient. Position fields by keyboard; dragging is not required.</p><div className="agp-field-types">{["Signature", "Initials", "Signed date", "Text", "Checkbox"].map(type => <button key={type} disabled={!draft.signers.length} onClick={() => { const id = Math.max(0, ...draft.fields.map(f => f.id)) + 1; change({ fields: [...draft.fields, { id, signer: draft.signers[0].id, type, page: 1, x: 8, y: 65 + Math.min(20, draft.fields.length * 5), required: true }] }); setSelectedField(id); }}><Plus size={14}/>{type}</button>)}</div><ul className="agp-field-list">{draft.fields.map(f => <li key={f.id}><button aria-pressed={selectedField === f.id} onClick={() => setSelectedField(f.id)}>{f.type}<small>{draft.signers.find(s => s.id === f.signer)?.name || "Unnamed signer"} · page {f.page}</small></button></li>)}</ul>{!draft.fields.length && <p className="agp-muted">Add a signature field to begin. No required field is inferred.</p>}{activeField && <div className="agp-field-properties"><label>Assigned signer<select aria-label="Assigned signer" value={activeField.signer} onChange={e => patchField({ signer: e.target.value })}>{draft.signers.map(s => <option key={s.id} value={s.id}>{s.name || "Unnamed signer"} · {s.role}</option>)}</select></label><div className="agp-form-row"><label>Left (%)<input type="number" min={0} max={55} value={activeField.x} onChange={e => patchField({ x: Math.max(0, Math.min(55, Number(e.target.value))) })}/></label><label>Top (%)<input type="number" min={0} max={90} value={activeField.y} onChange={e => patchField({ y: Math.max(0, Math.min(90, Number(e.target.value))) })}/></label></div><label className="agp-check"><input type="checkbox" checked={activeField.required} onChange={e => patchField({ required: e.target.checked })}/>Required</label><button onClick={() => { change({ fields: draft.fields.filter(f => f.id !== activeField.id) }); setSelectedField(null); }}><Trash2 size={15}/>Remove field</button></div>}<p className="agp-muted">Single-page layout simulation. Exact PDF pages, bounds, rotation and immutable field-map validation are production dependencies.</p></div>{documentPreview}</div>}
      {step === "review" && <div className="agp-layout"><div className="agp-editor"><h2>Review before requesting signatures</h2><dl className="agp-facts"><dt>Client</dt><dd>{draft.client || "Not selected"}</dd><dt>Document</dt><dd>Revision {draft.revision} · {draft.source}</dd><dt>Recipients</dt><dd>{draft.signers.map(s => s.name || "Unnamed signer").join(" → ") || "None"}</dd><dt>Fields</dt><dd>{draft.fields.length} assigned · {draft.ordered ? "Ordered signing" : "Parallel signing"}</dd><dt>Financial effect</dt><dd>No charge or payment request</dd></dl>{invalid() ? <div className="agp-error">{invalid()}<button onClick={() => go(!draft.client ? "document" : invalid().includes("signature") ? "fields" : "recipients")}>Correct preparation</button></div> : <p className="agp-ready"><Check size={18}/>Preparation checklist complete in this prototype.</p>}<p>Production review must bind the exact retained document, recipients, field map and approved commercial snapshot. Editing invalidates that approval.</p>{pending ? <div className="agp-approval" role="status"><ShieldCheck size={22}/><h3>Awaiting authorization</h3><p>No signature request has been sent. Production resumes through the existing approval gate.</p><button className="agp-primary" onClick={() => { if (condition !== "ready") { setError("The request outcome is not confirmed. Re-read before retrying."); return; } setPending(false); setStatus("Awaiting signatures"); go("detail"); setNotice("Mock authorized request issued. No customer message or signature link was created."); }}>Simulate canonical approval</button><button onClick={() => setPending(false)}>Cancel request</button></div> : <button className="agp-primary" disabled={Boolean(invalid()) || condition !== "ready"} onClick={() => setPending(true)}>Request authorization<ArrowRight size={16}/></button>}<button onClick={() => go("document")}>Return to editing</button></div>{documentPreview}</div>}
      {step === "detail" && <div className="agp-layout"><div className="agp-editor"><div className="agp-section-title"><h2>Signature progress</h2><span className="agp-state">{status}</span></div><ol className="agp-timeline"><li><strong>Document prepared</strong><small>Revision{draft.revision} · mock retained source</small></li>{status === "Draft" ? <li><strong>No signature request issued</strong><small>Draft correction does not send, sign or create a payment.</small></li> : <><li><strong>Request issued</strong><small>Issued is separate from provider delivery.</small></li><li><strong>Delivery not verified</strong><small>No provider receipt is present in this prototype.</small></li></>}{["Partially signed", "Completed"].includes(status) && <li><strong>{status === "Completed" ? "All signers completed" : "One signer completed"}</strong><small>Synthetic decision history only.</small></li>}</ol><div className="agp-recipients-summary">{draft.signers.map(s => <div key={s.id}><Users size={18}/><span><strong>{s.name || "Recipient"}</strong><small>{s.email} · {s.role}</small></span><span>{status === "Completed" ? "Signed (mock)" : "Awaiting signature"}</span></div>)}</div><h3>What happens next</h3><p>{status === "Completed" ? "Verify the sealed document and exact accepted terms. Review obligations and onboarding separately; no charge or service completion is inferred." : "Wait for supported evidence or propose an authorized follow-up. Delivery and document viewing are never guessed."}</p><button onClick={() => { go("recipient"); setRead(false); setConsent(false); setSignature(""); }}>Inspect recipient review path</button><button onClick={() => { setNotice("Follow-up proposed locally. Production must check consent, suppression, timing, exact content and canonical approval before sending."); }}>Propose follow-up</button><button onClick={() => { if (status !== "Completed") { setNotice("A completed retained PDF is not available. No file was invented."); return; } setNotice("Sealed document download is mocked. Production requires actual retained-byte verification."); }}>Download completed document</button>{status !== "Completed" && <button onClick={() => openDialog("void")}>Void signature request</button>}<button onClick={() => { setStatus("Draft"); change({ revision: draft.revision + 1, source: `New draft from revision ${draft.revision}` }); go("document"); }}>Prepare a new revision</button></div>{documentPreview}</div>}
      {step === "recipient" && <div className="agp-layout">{documentPreview}<div className="agp-editor"><h2>Review, then sign</h2><p>Prepared for {draft.signers[0]?.name || "the authorized recipient"}. Client Portal access must prove the business relationship and intended signer.</p><label className="agp-check"><input type="checkbox" checked={read} onChange={e => setRead(e.target.checked)}/>I have reviewed the entire document</label><label className="agp-check"><input type="checkbox" checked={consent} onChange={e => setConsent(e.target.checked)}/>I consent to electronic records and signatures under the applicable disclosed terms</label><label>Type your full name<input value={signature} onChange={e => setSignature(e.target.value)}/></label><button className="agp-primary" disabled={!read || !consent || !signature.trim() || condition !== "ready"} onClick={() => { setStatus(draft.signers.length > 1 ? "Partially signed" : "Completed"); go("detail"); setNotice("Demonstration signing decision only. No signature, consent evidence, payment or customer notification was recorded."); }}>Simulate signing decision</button><button onClick={() => { setStatus("Declined"); go("detail"); setNotice("Synthetic decline only. No real agreement was declined or notification sent."); }}>Simulate decline</button><button onClick={() => go("detail")}>Return without signing</button><p className="agp-muted">Disclosure version, identity, exact document, all assigned values and immutable native evidence remain production requirements.</p></div></div>}
      {steps.includes(step) && <footer className="agp-footer"><button onClick={() => step === "document" ? openDialog("leave") : go(steps[steps.indexOf(step) - 1])}><ArrowLeft size={16}/>{step === "document" ? "Close preparation" : "Back"}</button><span>Draft work is retained separately for each synthetic business.</span>{step !== "review" && <button className="agp-primary" onClick={next}>Continue to {labels[steps[steps.indexOf(step) + 1] as keyof typeof labels]}<ArrowRight size={16}/></button>}</footer>}
      </>}
    </section>
    <Dialog open={Boolean(dialog)} onOpenChange={open => !open && setDialog(null)}>
      <DialogContent onCloseAutoFocus={event => { event.preventDefault(); returnFocus.current?.focus(); }}>
        <DialogHeader><DialogTitle>{dialog === 'void' ? 'Void this signature request?' : dialog === 'leave-correction' ? 'Leave this correction?' : 'Leave preparation?'}</DialogTitle>
          <DialogDescription>{dialog === 'void' ? 'Production voiding revokes outstanding signing access and preserves the original document and audit record. This prototype only changes local state.' : dialog === 'leave-correction' ? correction?.phase === 'unknown' ? 'The original correction may still finish. Leaving does not cancel it. Review the current original record before another change.' : 'This proposal will be left without another save. The original agreement and its signing evidence are preserved.' : 'Your prototype draft stays in this browser session. Nothing has been sent. You can return from the register.'}</DialogDescription>
        </DialogHeader>
        <DialogFooter><button className="agp-dialog-button" onClick={() => setDialog(null)}>Keep working</button>
          <button className="agp-dialog-button" onClick={() => {
            if(dialog==='void'){setStatus('Voided');setNotice('Synthetic void decision only. No native record or token was changed.');}
            else if(dialog==='leave-correction'){setCorrection(null);go('detail');setNotice('Local proposal closed. Inspect the original recorded wording; no additional native request was made.');}
            else go('register');setDialog(null);
          }}>{dialog==='void'?'Simulate void':dialog==='leave-correction'?'Leave for current record':'Save locally and leave'}</button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  </>;
}

